"""Sum6 KES: checked against real keys and real headers, not against itself only."""
from __future__ import annotations

import json
from pathlib import Path

import cbor2
import pytest

from scripts import praos_kes

FIX = Path(__file__).resolve().parent / "fixtures" / "block_apply"
MAINNET_SLOTS_PER_KES_PERIOD = 129600


def test_cardano_cli_key_derives_its_published_verification_key():
    # kes.skey/kes.vkey were generated by `cardano-cli conway node key-gen-KES`.
    sk = praos_kes.load_sign_key(FIX / "kes.skey")
    assert len(sk) == 608
    assert praos_kes.derive_ver_key(sk) == praos_kes.load_ver_key(FIX / "kes.vkey")


def test_cardano_cli_key_right_subtree_seeds_regenerate_stored_keys():
    # Proves expand_seed + recursive key generation match cardano-crypto-class.
    assert praos_kes.check_sign_key(praos_kes.load_sign_key(FIX / "kes.skey"))


@pytest.mark.parametrize("index", [0, 1, 2])
def test_signature_is_byte_identical_to_haskell_signed_header(index):
    case = json.loads((FIX / "haskell-header-vectors.json").read_text())["cases"][index]
    header_bytes = bytes.fromhex(case["header"])
    body, signature = cbor2.loads(header_bytes)
    period = body[1] // case["praosSlotsPerKESPeriod"] - body[8][2]
    message = cbor2.dumps(body)
    assert message == header_bytes[1:1 + len(message)]  # canonical re-encoding
    ours = praos_kes.sign(bytes.fromhex(case["kesSignKey"]), period, message)
    assert ours == signature


def test_real_mainnet_header_signature_verifies_at_an_evolved_period():
    header_bytes = (FIX / "mainnet_blockheader_10817298.cbor").read_bytes()
    body, signature = cbor2.loads(header_bytes)
    hot_vk, _counter, kes_period, _sigma = body[8]
    period = body[1] // MAINNET_SLOTS_PER_KES_PERIOD - kes_period
    assert period > 0
    message = cbor2.dumps(body)
    assert praos_kes.verify(hot_vk, period, message, signature)
    assert not praos_kes.verify(hot_vk, period + 1, message, signature)
    assert not praos_kes.verify(hot_vk, period, message + b"\x00", signature)


@pytest.mark.parametrize("period", [0, 1, 31, 32, 33, 63])
def test_sign_verifies_at_every_subtree_boundary(period):
    sk = praos_kes.load_sign_key(FIX / "kes.skey")
    vk = praos_kes.derive_ver_key(sk)
    sig = praos_kes.sign(sk, period, b"dwarf")
    assert len(sig) == 448
    assert praos_kes.verify(vk, period, b"dwarf", sig)
    assert not praos_kes.verify(vk, (period + 1) % 64, b"dwarf", sig)


def test_sign_rejects_period_outside_the_key_lifetime():
    sk = praos_kes.load_sign_key(FIX / "kes.skey")
    with pytest.raises(ValueError):
        praos_kes.sign(sk, 64, b"x")
